import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'ok' | 'warning' | 'over';

interface Project {
  id: string;
  name: string;
  percentUsed: number;
  status: ProjectStatus;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' }> = {
  ok: { label: 'В рамках квоты', tone: 'success' },
  warning: { label: 'На пределе', tone: 'warning' },
  over: { label: 'Превышено', tone: 'danger' },
};

const STATUS_ORDER: ProjectStatus[] = ['ok', 'warning', 'over'];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Редизайн сайта', percentUsed: 82, status: 'ok' },
  { id: 'p2', name: 'Мобильное приложение', percentUsed: 96, status: 'warning' },
  { id: 'p3', name: 'Аналитика продукта', percentUsed: 108, status: 'over' },
  { id: 'p4', name: 'Онбординг клиентов', percentUsed: 45, status: 'ok' },
  { id: 'p5', name: 'Интеграция CRM', percentUsed: 100, status: 'warning' },
  { id: 'p6', name: 'Миграция базы данных', percentUsed: 120, status: 'over' },
  { id: 'p7', name: 'Маркетинговый сайт', percentUsed: 30, status: 'ok' },
  { id: 'p8', name: 'Внутренний портал', percentUsed: 88, status: 'warning' },
  { id: 'p9', name: 'API v2', percentUsed: 65, status: 'ok' },
  { id: 'p10', name: 'Биллинг', percentUsed: 115, status: 'over' },
  { id: 'p11', name: 'Служба поддержки', percentUsed: 55, status: 'ok' },
  { id: 'p12', name: 'Инфраструктура', percentUsed: 99, status: 'warning' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [selectedStatuses, setSelectedStatuses] = useState<ProjectStatus[]>([...STATUS_ORDER]);
  const [page, setPage] = useState(1);

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => selectedStatuses.includes(project.status)),
    [selectedStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visibleProjects = filteredProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE,
  );

  const toggleStatus = (status: ProjectStatus) => {
    setSelectedStatuses((current) =>
      current.includes(status) ? current.filter((item) => item !== status) : [...current, status],
    );
    setPage(1);
  };

  const removeStatus = (status: ProjectStatus) => {
    setSelectedStatuses((current) => current.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setSelectedStatuses([...STATUS_ORDER]);
    setPage(1);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4, 16px)',
        maxWidth: '560px',
      }}
    >
      <div style={{ display: 'flex', gap: 'var(--jx-space-2, 8px)', flexWrap: 'wrap' }}>
        {STATUS_ORDER.map((status) => {
          const isActive = selectedStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onClick={() => toggleStatus(status)}
              onRemove={() => removeStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {visibleProjects.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="По выбранным статусам нет проектов с расходом."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3, 12px)' }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-space-3, 12px)',
                  padding: 'var(--jx-space-3, 12px)',
                  borderRadius: 'var(--jx-radius-md)',
                  background: 'var(--jx-color-surface)',
                }}
              >
                <span style={{ flex: 1, color: 'var(--jx-color-text)' }}>{project.name}</span>
                <JxProgressCircle value={project.percentUsed} showValue />
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

